#define FOV 60.0
#define MAX_DIST 32.0
#define MAX_STEPS 512
#define CAMERA_POS vec3(0, 0, -10)
#define LIGHT_POS vec3(0, 100, -100)
#define WAVE_ITERATIONS 12

const float PI = 3.1415926;
const float EPSILON = 0.001;

vec3 rotateX(in vec3 v, in float theta)
{
    float sin = sin(theta);
    float cos = cos(theta);
    return v *= mat3(1, 0, 0, 0, cos, -sin, 0, sin, cos);
}

vec3 rotateY(in vec3 v, in float theta)
{
    float sin = sin(theta);
    float cos = cos(theta);
    return v *= mat3(cos, 0, sin, 0, 1, 0, -sin, 0, cos);
}

vec3 rotateZ(in vec3 v, in float theta)
{
    float sin = sin(theta);
    float cos = cos(theta);
    return v *= mat3(cos, -sin, 0, sin, cos, 0, 0, 0, 1);
}

vec3 mouseControl(in vec3 p)
{
    vec2 m = iMouse.xy / iResolution.xy - 3.5;
    p = rotateX(p, -m.y * PI * 0.5 - 0.5);
    p = rotateZ(p, -m.x * 2.0 * PI + PI);

    return p;
}

vec2 wavedx(vec2 position, vec2 direction, float frequency, float timeshift) 
{
  float x = dot(direction, position) * frequency + timeshift;
  float wave = sin(x);
  float dx = cos(x);
  return vec2(wave, -dx);
}

// https://www.shadertoy.com/view/MdXyzX
float getWaves(vec2 position) 
{
  float wavePhaseShift = length(position) * 0.1; // this is to avoid every octave having exactly the same phase everywhere
  float iter = 0.0; // this will help generating well distributed wave directions
  float frequency = 1.0; // frequency of the wave, this will change every iteration
  float timeMultiplier = 2.0; // time multiplier for the wave, this will change every iteration
  float weight = 1.0;// weight in final sum for the wave, this will change every iteration
  float sumOfValues = 0.0; // will store final sum of values
  float sumOfWeights = 0.0; // will store final sum of weights
  for(int i=0; i < WAVE_ITERATIONS; i++) {
    // generate some wave direction that looks kind of random
    vec2 p = vec2(sin(iter), cos(iter));

    // calculate wave data
    vec2 res = wavedx(position, p, frequency, iTime * timeMultiplier + wavePhaseShift);

    // shift position around according to wave drag and derivative of the wave
    position += p * res.y * weight * 0.05;

    // add the results to sums
    sumOfValues += res.x * weight;
    sumOfWeights += weight;

    // modify next octave ;
    weight = mix(weight, 0.0, 0.1);
    frequency *= 1.22;
    timeMultiplier *= 1.07;

    // add some kind of random value to make next wave look random too
    iter += 1232.399963;
  }
  // calculate and return
  return sumOfValues / sumOfWeights;
}

float particle(vec3 p)
{
    return 4.0*exp(-(p.x * p.x + p.y * p.y));
}

