float toggle(float x, float value)
{
    return 0.5 + atan(x * x - value * value) / PI;
}

// Change functions here
vec3 getSDF(vec3 p)
{
    p = mouseControl(p);

    float sdf = p.z + toggle(iTime, 2.0) * particle(p) + 0.8*getWaves(p.xy);

    vec3 res = vec3(abs(sdf), 0, 0);

    return res;
}

float saturate (float x)
{
    return min(1.0, max(0.0,x));
}
vec3 saturate (vec3 x)
{
    return min(vec3(1.,1.,1.), max(vec3(0.,0.,0.),x));
}

vec3 jet(float w) 
{
    float x = saturate(w);
	vec3 c;

	if (x < 0.25)
		c = vec3(0.0, 4.0 * x, 1.0);
	else if (x < 0.5)
		c = vec3(0.0, 1.0, 1.0 + 4.0 * (0.25 - x));
	else if (x < 0.75)
		c = vec3(4.0 * (x - 0.5), 1.0, 0.0);
	else
		c = vec3(1.0, 1.0 + 4.0 * (0.75 - x), 0.0);

	return saturate(c);
}

vec3 getColor(vec3 p)
{
    p = mouseControl(p);

    return jet(abs(p.z) * 0.5);
    //return vec3(1, 0, 0);
}

vec3 getNormal(vec3 p)
{
    vec2 e = vec2(EPSILON, 0.0);
    vec3 n = vec3(getSDF(p).x) - vec3(getSDF(p - e.xyy).x, getSDF(p - e.yxy).x, getSDF(p - e.yyx).x);
    return normalize(n);
}

float getSoftShadow(vec3 p, vec3 lightPos)
{
    float res = 1.0;
    float dist = EPSILON;
    float lightSize = 0.03;

    for(int i = 0; i < MAX_STEPS; i++)
    {
        vec3 hit = getSDF(p + lightPos * dist);

        res = min(res, hit.x / (dist * lightSize));
        dist += hit.x;

        if(hit.x < EPSILON || dist > 60.0)
        {
            break;
        }
    }
    return clamp(res, 0.0, 1.0);
}

float getAmbientOcclusion(vec3 p, vec3 normal)
{
    float occ = 0.0;
    float weight = 1.0;

    for(int i = 0; i < 8; i++)
    {
        float len = 0.01 + 0.02 * float(i * i);
        float dist = getSDF(p + normal * len).x;
        occ += (len - dist) * weight;
        weight *= 0.85;
    }

    return 1.0 - clamp(0.6 * occ, 0.0, 1.0);
}

vec3 getLight(vec3 p, vec3 rd, float waveFunction, float sphericalHarmonics, vec3 lightPos)
{
    vec3 finalCol = vec3(0, 0, 0);
    vec3 v = -rd;
    vec3 n = getNormal(p);

    vec3 col = getColor(p);

    vec3 l = normalize(lightPos - p);
    vec3 R = reflect(-l, n);
    vec3 H = normalize(l + v);

    vec3 ambient = col * 0.1;
    vec3 diffuse = col * clamp(dot(l, n), 0.0, 1.0);
    vec3 specColor = vec3(1.0);
    vec3 specular = specColor * pow(clamp(dot(R, v), 0.0, 1.0), 128.0);

    // Soft Shadows
    float shadow = getSoftShadow(p + n * 0.02, lightPos);

    // Ambient occlusion
    float occ = getAmbientOcclusion(p, n);

    // Reflections
    vec3 back = 0.05 * col * clamp(dot(n, -l), 0.0, 1.0);

    finalCol = (ambient + back) * occ + (diffuse ) * shadow;

    return finalCol;
}

vec4[2] rayMarch(vec3 ro, vec3 rd, vec3 lightPos)
{
    vec3 hit;
    vec3 object;
    vec3 oh = vec3(0);
    vec4 tmp = vec4(0);

    for(int i = 0; i < MAX_STEPS; i++)
    {
        // Raymarching
        vec3 p = ro + object.x * rd;
        hit = getSDF(p);

        float px = 2.0 / iResolution.y;
        float th1 = px * object.x;
        th1 *= 1.5;

        object.x += hit.x * 0.085; //* 0.085
        object.y = hit.y;
        object.z = hit.z;
        int index = int(object.y) - 1;

        if(abs(hit.x) < EPSILON || object.x > float(MAX_DIST))
        {
            break;
        }
    }

    vec4[2] res = vec4[](vec4(object, 0), tmp);
    return res;
}

vec3 render(in vec2 uv)
{
    vec3 ro = CAMERA_POS;

    float invTanFOV = 1.0 / (tan(FOV / 2.0 * PI / 180.0));
    vec3 rd = normalize(vec3(uv, invTanFOV));

    vec4 object[2] = rayMarch(ro, rd, LIGHT_POS);
    vec3 col;

    if(object[0].x < float(MAX_DIST))
    {
        vec3 p = ro + object[0].x * rd;

        col = getLight(p, rd, object[0].y, object[0].z, LIGHT_POS);
    }
    else
    {
        col = vec3(0); // Background color
    }

    float blendFactor = smoothstep(0.0, MAX_DIST, object[0].x);
    col = vec3(mix(col, vec3(0), blendFactor));

    return col;
}

vec2 getUV(in vec2 offset, in vec2 fragCoord)
{
    return (2.0 * fragCoord.xy + offset - iResolution.xy) / iResolution.y;
}

// MSAAx1 (default)
vec3 renderAAx1(in vec2 fragCoord)
{
    return render(getUV(vec2(0), fragCoord));
}

// MSAAx2 (slow)
vec3 renderAAx2(in vec2 fragCoord)
{
    float bxy = float(int(fragCoord.x + fragCoord.y) & 1);
    float nbxy = 1. - bxy;
    vec3 colAA = (render(getUV(vec2(0.33 * nbxy, 0.), fragCoord)) + render(getUV(vec2(0.33 * bxy, 0.66), fragCoord)));
    return colAA / 2.0;
}

// MSAAx3 (slower)
vec3 renderAAx3(in vec2 fragCoord)
{
    float bxy = float(int(fragCoord.x + fragCoord.y) & 1);
    float nbxy = 1. - bxy;
    vec3 colAA = (render(getUV(vec2(0.66 * nbxy, 0.), fragCoord)) + render(getUV(vec2(0.66 * bxy, 0.66), fragCoord)) + render(getUV(vec2(0.33, 0.33), fragCoord)));
    return colAA / 3.0;
}

// MSAAx4 (the slowest)
vec3 renderAAx4(in vec2 fragCoord)
{
    vec4 e = vec4(0.125, -0.125, 0.375, -0.375);
    vec3 colAA = render(getUV(e.xz, fragCoord)) + render(getUV(e.yw, fragCoord)) + render(getUV(e.wx, fragCoord)) + render(getUV(e.zy, fragCoord));
    return colAA /= 4.0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 col = renderAAx1(fragCoord);
    fragColor = vec4(col, 1.0);
}
